import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadLora = makeLoadFont('Lora');
const loadInter = makeLoadFont('Inter');

const { fontFamily: lora } = loadLora();
const { fontFamily: inter } = loadInter();



export type ArticlePopupProps = Record<string, any>;

const ArticlePopup: React.FC<ArticlePopupProps> = ({
  backgroundColor = "#E6E9EC",
  transparentBackground = false,
  durationInSeconds = 12,
  accentColor = "#0056B3",
  windowTitle = "Journal of Algorithmic Medicine",
  headline = "Correlation Between Nociceptive Stimuli and Subjective Value Attribution",
  author = "Dr. E. Malloy, PhD, et al.",
  dateStr = "Vol. 42, Issue 7 | 2023",
  paragraphs = [
    "Abstract: This study investigates the neurobiological and psychological mechanisms underlying the valuation of outcomes achieved through varying degrees of physical or cognitive distress.",
    "Our findings indicate a statistically significant positive correlation (r = 0.84, p < 0.01) between the intensity of perceived hardship during task execution and the subjective valuation of the resulting reward.",
    "These results challenge traditional utility models, suggesting that human reward circuitry inherently discounts effortlessly acquired assets while hyper-valuing those associated with nociceptive or stress-response activation.",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // ANIMATION CALCULATIONS

  // 1. Initial window pop-up
  const windowScale = spring({
    fps,
    frame: frame - 10,
    config: { damping: 14, mass: 0.8 },
  });
  
  const windowOpacity = interpolate(frame, [10, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Automated slow scroll to simulate reading/decryption
  // Starts after 2 seconds, ends 1 second before completion
  const scrollProgress = interpolate(
    frame,
    [fps * 2, fps * (durationInSeconds - 1)],
    [0, -400],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 3. Pulse indicator for "live" feel
  const pulseOpacity = interpolate(
    frame % 40,
    [0, 20, 40],
    [0.3, 1, 0.3]
  );

  // 4. Header typing effect / reveal
  const headerOpacity = interpolate(frame, [25, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Background Subtle Medical Grid Simulation (Static overlay) */}
      <AbsoluteFill
        style={{
          background:
            "repeating-linear-gradient(0deg, rgba(0,0,0,0.03), rgba(0,0,0,0.03) 1px, transparent 1px, transparent 40px), repeating-linear-gradient(90deg, rgba(0,0,0,0.03), rgba(0,0,0,0.03) 1px, transparent 1px, transparent 40px)",
          opacity: 0.7,
        }}
      />

      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Main Popup Window */}
        <div
          style={{
            width: width * 0.85,
            height: height * 0.75,
            backgroundColor: "#FFFFFF",
            border: `1px solid #D1D5DB`,
            boxShadow: `0 20px 50px rgba(0,0,0,0.1), 0 4px 12px rgba(0,0,0,0.05)`,
            display: "flex",
            flexDirection: "column",
            transform: `scale(${windowScale})`,
            opacity: windowOpacity,
            position: "relative",
            overflow: "hidden",
            borderRadius: 4,
          }}
        >
          {/* Top Window Bar - PDF Viewer Style */}
          <div
            style={{
              height: 60,
              backgroundColor: "#F3F4F6",
              borderBottom: `1px solid #E5E7EB`,
              display: "flex",
              alignItems: "center",
              padding: "0 24px",
              justifyContent: "space-between",
              flexShrink: 0,
            }}
          >
            <span
              style={{
                fontFamily: inter,
                fontSize: 22,
                fontWeight: 600,
                color: "#374151",
                letterSpacing: "-0.02em",
              }}
            >
              {windowTitle}
            </span>
            <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
              <div
                style={{
                  width: 10,
                  height: 10,
                  backgroundColor: accentColor,
                  borderRadius: "50%",
                  opacity: pulseOpacity,
                }}
              />
              <span
                style={{
                  fontFamily: inter,
                  fontSize: 16,
                  fontWeight: 600,
                  color: "#6B7280",
                  letterSpacing: "0.05em",
                }}
              >
                OPEN ACCESS
              </span>
            </div>
          </div>

          {/* Scrollable Content Container */}
          <div
            style={{
              flex: 1,
              padding: "60px 48px",
              display: "flex",
              flexDirection: "column",
              gap: 32,
              transform: `translateY(${scrollProgress}px)`,
            }}
          >
            {/* Meta Info */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 12,
                opacity: headerOpacity,
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  fontFamily: inter,
                  fontSize: 20,
                  color: "#4B5563",
                  borderBottom: `2px solid ${accentColor}`,
                  paddingBottom: 16,
                  fontWeight: 500,
                }}
              >
                <span>{author}</span>
                <span>{dateStr}</span>
              </div>
            </div>

            {/* Headline */}
            <h1
              style={{
                fontFamily: lora,
                fontSize: 56,
                fontWeight: 700,
                color: "#111827",
                margin: 0,
                lineHeight: 1.15,
                opacity: headerOpacity,
              }}
            >
              {headline}
            </h1>

            {/* Paragraphs */}
            <div style={{ display: "flex", flexDirection: "column", gap: 28, marginTop: 12 }}>
              {paragraphs.map((text, i) => {
                const staggerDelay = 40 + i * 15;
                const pOpacity = interpolate(
                  frame,
                  [staggerDelay, staggerDelay + 20],
                  [0, 1],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );
                const pY = interpolate(
                  frame,
                  [staggerDelay, staggerDelay + 20],
                  [40, 0],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                    easing: Easing.out(Easing.quad),
                  }
                );

                return (
                  <p
                    key={i}
                    style={{
                      fontFamily: lora,
                      fontSize: 32,
                      lineHeight: 1.6,
                      color: "#374151",
                      margin: 0,
                      opacity: pOpacity,
                      transform: `translateY(${pY}px)`,
                      fontWeight: i === 0 ? 600 : 400, // Make the abstract/first paragraph slightly bolder
                    }}
                  >
                    {text}
                  </p>
                );
              })}
            </div>
            
            {/* End of file indicator */}
            <div
               style={{
                  marginTop: 60,
                  fontFamily: inter,
                  fontSize: 20,
                  fontWeight: 600,
                  color: "#9CA3AF",
                  textAlign: "center",
                  letterSpacing: "0.1em",
                  opacity: interpolate(frame, [fps * durationInSeconds - 40, fps * durationInSeconds - 20], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })
               }}
            >
               [ END OF ARTICLE ]
            </div>
          </div>
          
          {/* Edge shadow to simulate screen depth / fade out at bottom */}
          <div 
             style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: 120,
                background: `linear-gradient(to top, #FFFFFF 10%, transparent)`,
                pointerEvents: "none",
             }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ArticlePopup;